const TEXTS = ['x =', '\u2212b', ' \u00b1 ', 'b\u00b2', ' \u2212 4', 'a', 'c', '2', 'a', '2', 'x\u00b2', ' \u2212 ', '7', 'x', ' + ', '3', ' = 0', '\u0394 = ', 'b\u00b2', ' \u2212 4', 'a', 'c', ' = 25', 'a = 2', 'b = \u22127', 'c = 3'];

const DARK = '#22303f';
const RED = '#c0392b';
const BLUE = '#1a6fd4';
const GREEN = '#1e8e4e';

const META = [
  { fs: 34, c: DARK },
  { fs: 34, c: BLUE },
  { fs: 34, c: DARK },
  { fs: 32, c: BLUE },
  { fs: 32, c: DARK },
  { fs: 32, c: RED },
  { fs: 32, c: GREEN },
  { fs: 32, c: DARK },
  { fs: 32, c: RED },
  { fs: 36, c: RED },
  { fs: 36, c: DARK },
  { fs: 36, c: BLUE },
  { fs: 36, c: BLUE },
  { fs: 36, c: DARK },
  { fs: 36, c: DARK },
  { fs: 36, c: GREEN },
  { fs: 36, c: DARK },
  { fs: 28, c: DARK },
  { fs: 28, c: BLUE },
  { fs: 28, c: DARK },
  { fs: 28, c: RED },
  { fs: 28, c: GREEN },
  { fs: 28, c: DARK },
  { fs: 28, c: RED },
  { fs: 28, c: BLUE },
  { fs: 28, c: GREEN }
];

const visual = {
  prepare: function (input) {
    var out = [];
    for (var i = 0; i < TEXTS.length; i++) {
      out.push({ kind: 'text', payload: TEXTS[i] });
    }
    return out;
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var BW = 900;
    var BH = 620;
    var s = Math.min(W / BW, H / BH);
    if (!isFinite(s) || s <= 0) { s = 1; }
    var ox = (W - BW * s) / 2;
    var oy = (H - BH * s) / 2;

    function px(x) { return Math.round((ox + x * s) * 100) / 100; }
    function py(y) { return Math.round((oy + y * s) * 100) / 100; }
    function pf(f) { return Math.round(f * s * 100) / 100; }

    function wEst(str, fs) {
      var w = 0;
      for (var k = 0; k < str.length; k++) {
        var ch = str.charAt(k);
        var cc = str.charCodeAt(k);
        if (ch === ' ') { w += 0.28; }
        else if (ch === '\u00b2') { w += 0.5; }
        else if (ch === '\u0394') { w += 0.72; }
        else if (ch === '\u2212' || ch === '\u00b1' || ch === '=' || ch === '+') { w += 0.62; }
        else if (ch === 'x') { w += 0.5; }
        else if (cc > 0x2e80) { w += 1.0; }
        else { w += 0.55; }
      }
      return w * fs;
    }

    var widths = [];
    var i;
    for (i = 0; i < TEXTS.length; i++) {
      var est = wEst(TEXTS[i], META[i].fs);
      var m = metrics && metrics[i];
      if (m && typeof m.width === 'number' && m.width > 0) {
        var mw = m.width;
        if (typeof m.fontSize === 'number' && m.fontSize > 0) {
          mw = m.width * META[i].fs / m.fontSize;
        }
        if (mw > est * 0.7 && mw < est * 1.5) { est = mw; }
      }
      widths.push(est);
    }

    var GAPRAD = 16;
    var numW = GAPRAD;
    for (i = 0; i <= 6; i++) { numW += widths[i]; }
    var numX = 450 - numW / 2;
    var numY = 175;
    var nx = [];
    var cur = numX;
    for (i = 0; i <= 6; i++) {
      if (i === 3) { cur += GAPRAD; }
      nx.push(cur);
      cur += widths[i];
    }
    var numRight = cur;

    var radL = nx[3];
    var radR = nx[6] + widths[6];
    var barLeft = nx[1] - 8;
    var barY = 206;
    var denW = widths[7] + widths[8];
    var denX = (barLeft + numRight) / 2 - denW / 2;
    var denY = 250;

    var eqW = 0;
    for (i = 9; i <= 16; i++) { eqW += widths[i]; }
    var eqX = 450 - eqW / 2;
    var eqY = 400;
    var ex = [];
    cur = eqX;
    for (i = 9; i <= 16; i++) { ex.push(cur); cur += widths[i]; }

    var dW = 0;
    for (i = 17; i <= 22; i++) { dW += widths[i]; }
    var dX = 450 - dW / 2;
    var dY = 566;
    var dl = [];
    cur = dX;
    for (i = 17; i <= 22; i++) { dl.push(cur); cur += widths[i]; }

    var boxTop = 452;
    var boxH = 52;
    var boxW = 160;
    var BC = [170, 450, 730];
    var BCOL = [RED, BLUE, GREEN];
    var BFILL = ['#fdeeec', '#eaf1fb', '#e9f6ee'];

    function lineCmd(x1, y1, x2, y2) {
      return ['M', px(x1), py(y1), 'L', px(x2), py(y2)];
    }
    function polyCmd(pts) {
      var c = ['M', px(pts[0][0]), py(pts[0][1])];
      for (var k = 1; k < pts.length; k++) {
        c.push('L', px(pts[k][0]), py(pts[k][1]));
      }
      return c;
    }
    function rectCmd(x, y, w, h) {
      return ['M', px(x), py(y), 'L', px(x + w), py(y), 'L', px(x + w), py(y + h), 'L', px(x), py(y + h), 'Z'];
    }
    function circleCmd(cx, cy, r) {
      var k = 0.5523 * r;
      return ['M', px(cx), py(cy - r),
        'C', px(cx + k), py(cy - r), px(cx + r), py(cy - k), px(cx + r), py(cy),
        'C', px(cx + r), py(cy + k), px(cx + k), py(cy + r), px(cx), py(cy + r),
        'C', px(cx - k), py(cy + r), px(cx - r), py(cy + k), px(cx - r), py(cy),
        'C', px(cx - r), py(cy - k), px(cx - k), py(cy - r), px(cx), py(cy - r),
        'Z'];
    }

    var paths = [];
    var nodes = [];
    var labels = [];

    paths.push({ id: 'fracbar', commands: lineCmd(barLeft, barY, numRight, barY) });
    nodes.push({ type: 'path', pathId: 'fracbar', stroke: DARK, strokeWidth: pf(2.4), fill: 'none' });

    paths.push({ id: 'radical', commands: polyCmd([[radL - 22, 166], [radL - 12, 178], [radL - 2, 141], [radR + 9, 141]]) });
    nodes.push({ type: 'path', pathId: 'radical', stroke: DARK, strokeWidth: pf(2.4), fill: 'none' });

    var glyphC = [ex[0] + widths[9] / 2, ex[3] + widths[12] / 2, ex[6] + widths[15] / 2];
    for (i = 0; i < 3; i++) {
      paths.push({ id: 'cn' + i, commands: lineCmd(glyphC[i], 420, BC[i], boxTop - 4) });
      nodes.push({ type: 'path', pathId: 'cn' + i, stroke: BCOL[i], strokeWidth: pf(2), fill: 'none' });

      paths.push({ id: 'dt' + i, commands: circleCmd(glyphC[i], 420, 3.2) });
      nodes.push({ type: 'path', pathId: 'dt' + i, fill: BCOL[i], stroke: BCOL[i] });

      paths.push({ id: 'bx' + i, commands: rectCmd(BC[i] - boxW / 2, boxTop, boxW, boxH) });
      nodes.push({ type: 'path', pathId: 'bx' + i, stroke: BCOL[i], strokeWidth: pf(2), fill: BFILL[i] });
    }

    paths.push({ id: 'dbox', commands: rectCmd(270, 528, 360, 56) });
    nodes.push({ type: 'path', pathId: 'dbox', stroke: '#8898a8', strokeWidth: pf(2), fill: '#f4f6f9' });

    function lab(idx, x, y, anchor) {
      labels.push({
        type: 'label',
        text: TEXTS[idx],
        x: px(x),
        y: py(y),
        fontSize: pf(META[idx].fs),
        fill: META[idx].c,
        anchor: anchor || 'start'
      });
    }

    for (i = 0; i <= 6; i++) { lab(i, nx[i], numY, 'start'); }
    lab(7, denX, denY, 'start');
    lab(8, denX + widths[7], denY, 'start');
    for (i = 9; i <= 16; i++) { lab(i, ex[i - 9], eqY, 'start'); }
    for (i = 17; i <= 22; i++) { lab(i, dl[i - 17], dY, 'start'); }
    lab(23, BC[0], boxTop + 34, 'middle');
    lab(24, BC[1], boxTop + 34, 'middle');
    lab(25, BC[2], boxTop + 34, 'middle');

    var children = nodes.concat(labels);

    return {
      schemaVersion: 1,
      sceneId: 'quadratic-formula-figure',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
